// ⌘/Ctrl+V pastes a clipboard image straight into the editor without triggering
// the browser's clipboard-read permission prompt (a real paste gesture exposes
// clipboardData directly). Only hijacks the paste when an image is actually
// present, so pasting text into name/URL fields still works.
$('#dlgResearcherEditor').addEventListener('paste',async e=>{
  if(!researcherEditorDraft) return;
  const items=(e.clipboardData&&e.clipboardData.items)||[];
  for(const item of items){
    if(item.kind==='file'&&String(item.type||'').startsWith('image/')){
      const blob=item.getAsFile();
      if(blob){ e.preventDefault(); await applyResearcherEditorImageBlob(blob); return; }
    }
  }
});
// ⌘/Ctrl+V pastes a clipboard image onto the selected reference (its figure
// image) without the clipboard-read permission prompt. Only hijacks the paste
// when an image is actually present, so pasting text into title/notes still works.
// Enter in the corresponding-author combobox adds the typed/picked value.
$('#detail').addEventListener('keydown',e=>{
  if(e.key==='Enter' && e.target && e.target.id==='corrAddInput'){ e.preventDefault(); addCorrespondingFromInput(); }
});
// Picking an author from the datalist should add it instantly — no "Add" click.
// `inputType` for a datalist pick isn't reliable across browsers, so instead
// check whether the field's value now exactly matches one of the datalist's
// options (which is true right after a pick, and also once free typing happens
// to complete to a listed name — fine either way).
$('#detail').addEventListener('input',e=>{
  if(e.target && e.target.id==='corrAddInput'){
    const val=e.target.value.trim();
    const dl=document.getElementById('corrAuthorList');
    if(val && dl && Array.from(dl.options).some(o=>o.value===val)) addCorrespondingFromInput();
  }
});
$('#detail').addEventListener('paste',async e=>{
  if(currentView!=='items') return;
  const it=lib.items.find(x=>x.id===selectedId); if(!it) return;
  const items=(e.clipboardData&&e.clipboardData.items)||[];
  for(const item of items){
    if(item.kind==='file'&&String(item.type||'').startsWith('image/')){
      const blob=item.getAsFile();
      if(blob){ e.preventDefault(); await setItemImage(it, blob); return; }
    }
  }
});

$('#fileResearcherAiJson').addEventListener('change',async e=>{
  const file=e.target.files&&e.target.files[0]; e.target.value=''; if(!file) return;
  if(file.size>1024*1024){ showToast(t('researcherAiFileTooLarge'),true); return; }
  try{ const text=await file.text(); researcherEditorAiState.jsonText=text; researcherAiReview(text); }
  catch(err){ console.error(err); showToast(t('researcherAiFileReadError'),true); }
});

function updateCitationPrefFromEvent(e){
  if(e.target.dataset.pref){
    const key = e.target.dataset.pref;
    citationPrefs[key] = (key==='includeTitle' || key==='includeUrl') ? e.target.checked : e.target.value;
    localStorage.setItem('refshelf.citationPrefs', JSON.stringify(citationPrefs));
    updateCitePreview();
    return true;
  }
  return false;
}
$('#dlgCitationPrefs').addEventListener('change', updateCitationPrefFromEvent);
$('#detail').addEventListener('change', (e)=>{
  if(updateCitationPrefFromEvent(e)) return;
});
$('#detail').addEventListener('click', async (e)=>{
  if(currentView==='researchers'){
    const paper=e.target.closest('[data-researcher-paper]');
    if(paper){ currentView='items'; selectedId=paper.dataset.researcherPaper; renderAll(); return; }
    return;
  }
  // 表示設定: reorder blocks with the ↑/↓ buttons (global preference)
  const moveBtn = e.target.closest('[data-detail-move]');
  if(moveBtn){
    const key=moveBtn.dataset.block, ord=referenceDetailPrefs.order, i=ord.indexOf(key), j=moveBtn.dataset.detailMove==='up'?i-1:i+1;
    if(i>=0 && j>=0 && j<ord.length){ [ord[i],ord[j]]=[ord[j],ord[i]]; saveReferenceDetailPrefs(); renderDetail(); }
    return;
  }
  const btn = e.target.closest('[data-act],[data-open-att],[data-del-att]');
  if(!btn) return;
  const it = lib.items.find(x=>x.id===selectedId);
  if(!it) return;
  if(btn.dataset.openAtt !== undefined){ openAttachment(it.attachments[+btn.dataset.openAtt].name); return; }
  if(btn.dataset.delAtt !== undefined){
    const a = it.attachments[+btn.dataset.delAtt];
    if(!confirm(I18N[lang].confirmDeleteAtt(a.name))) return;
    pendingAttachmentDeletes.add(a.name);
    it.attachments.splice(+btn.dataset.delAtt,1);
    touch(it); renderList(); renderDetail();
    showToast(t('attDeleted'));
    return;
  }
  switch(btn.dataset.act){
    case 'toggleEdit': detailEditMode=!detailEditMode; renderDetail(); break;
    case 'detailSettings': referenceDetailSettingsOpen=!referenceDetailSettingsOpen; renderDetail(); break;
    case 'openlink': openExternalLink(it.url || ('https://doi.org/' + it.doi)); break;
    case 'copycite': {
      await copyCitation(it, citationPrefs); showToast(t('copied'));
      const cp=btn.closest('.cpCopy');
      if(cp){ cp.classList.add('copied'); cp.innerHTML=`${ic('check')}<span class="tbtnLabel">${esc(t('copy'))}</span>`;
        setTimeout(()=>{ if(cp.isConnected){ cp.classList.remove('copied'); cp.innerHTML=`${ic('copy')}<span class="tbtnLabel">${esc(t('copy'))}</span>`; } }, 1400); }
      break;
    }
    case 'copybib': await navigator.clipboard.writeText(itemToBibTeX(it)); showToast(t('copied')); break;
    case 'citeprefs': openCitationPrefsDialog(); break;
    case 'toggleStar': toggleStar(it.id); break;
    case 'toggleMyPublication': toggleMyPublication(it.id); break;
    case 'addpdf': $('#filePdf').click(); break;
    case 'pasteImage': await pasteItemImageFromClipboard(it); break;
    case 'pickImage': $('#fileImage').click(); break;
    case 'removeImage': removeItemImage(it); break;
    case 'delitem': await deleteItem(it.id); break;
    case 'restoreItem': await restoreItem(it.id); break;
    case 'deleteForever': await deleteForever(it.id); break;
    case 'citations': openCitationsDialog(it); break;
    case 'graph': openGraphDialog(it); break;
    case 'researcherMap': openResearcherMap(it); break;
    case 'updateThis': await updateSingleItem(it); break;
    case 'applyJournalFix': {
      const sug = fixSuggestionForItem(it);
      if(sug && applyJournalFixSuggestion(sug)){
        renderList(); renderDetail();
      }
      break;
    }
    case 'ignoreJournalFix': {
      const sug = fixSuggestionForItem(it);
      if(sug && ignoreFixSuggestion(sug)){
        renderDetail(); updateAlerts();
      }
      break;
    }
  }
});
// Per-item update: refresh cited-by + corresponding authors for exactly one item,
// bypassing the freshness cache (the user explicitly asked for this one).
async function updateSingleItem(it){
  await refreshCitedByCounts([it], {force:true});
  await refreshCorrespondingAuthors([it], {force:true});
  if(await enrichCategory(it)){ touch(); refreshRowCells(it); renderDetail(); }
}
$('#filePdf').addEventListener('change', async ()=>{
  const it = lib.items.find(x=>x.id===selectedId);
  if(it && $('#filePdf').files.length) await attachFiles(it, Array.from($('#filePdf').files));
  $('#filePdf').value = '';
});
$('#fileImage').addEventListener('change', async ()=>{
  const it = lib.items.find(x=>x.id===selectedId);
  const file = $('#fileImage').files[0];
  if(it && file) await setItemImage(it, file, file.name);
  $('#fileImage').value = '';
});
$('#fileResearcherImage').addEventListener('change', async ()=>{
  const file=$('#fileResearcherImage').files[0];
  $('#fileResearcherImage').value='';
  if(!file) return;
  if($('#dlgResearcherEditor').open && researcherEditorDraft){
    if(!String(file.type||'').startsWith('image/')){ showToast(t('researcherImageUnavailable'),true); return; }
    if(file.size>2*1024*1024){ showToast(t('researcherImageTooLarge'),true); return; }
    try{ researcherEditorDraft.imageUrl=await researcherImageDataUrl(file); researcherEditorResetCrop(researcherEditorDraft); markResearcherFieldSource(researcherEditorDraft,'imageUrl','manual'); researcherEditorMarkDirty(); renderResearcherEditor(); }
    catch(err){ console.error(err); showToast(t('researcherImageUnavailable'),true); }
    return;
  }
  const p=ensureResearcherProfileForDetail(); // register on first image if needed
  if(p) await setResearcherImage(p,file);
});
